"""Read-only detection of Chromium certificate warning pages."""

_CODES = frozenset({
    "ERR_CERT_AUTHORITY_INVALID", "ERR_CERT_COMMON_NAME_INVALID",
    "ERR_CERT_DATE_INVALID", "ERR_CERT_INVALID", "ERR_CERT_REVOKED",
    "ERR_CERT_WEAK_SIGNATURE_ALGORITHM", "ERR_CERT_WEAK_KEY",
    "ERR_CERT_NAME_CONSTRAINT_VIOLATION", "ERR_CERT_VALIDITY_TOO_LONG",
    "ERR_CERTIFICATE_TRANSPARENCY_REQUIRED",
    "ERR_SSL_PINNED_KEY_NOT_IN_CERT_CHAIN",
})


def detect_certificate_warning(driver):
    """Return safe observed evidence, or None; never navigate or click."""
    from selenium.common.exceptions import WebDriverException

    try:
        evidence = driver.execute_script("""
            const page = document.querySelector('.interstitial-wrapper');
            if (!page || !page.querySelector('#main-content') ||
                !page.querySelector('#details-button') ||
                !page.getClientRects().length) return null;
            const node = page.querySelector('#error-code');
            const value = node ? node.textContent.trim().toUpperCase() : '';
            const code = value.replace(/^NET::/, '');
            const known = arguments[0].includes(code);
            const ssl = document.body.classList.contains('ssl') ||
                        document.body.classList.contains('badclock');
            if (!known && !ssl) return null;
            return {code: known ? code : ''};
        """, sorted(_CODES))
    except WebDriverException:
        # Navigation may still be replacing the document; caller can retry.
        return None

    if not isinstance(evidence, dict):
        return None
    code = evidence.get("code")
    if not isinstance(code, str) or code not in _CODES:
        return {"reason": "Browser certificate warning detected; cause not verified"}
    return {
        "reason": "Browser reported certificate error: " + code,
        "browser_code": code,
    }
